messages.content:
[tool error]
{
  "ok": false,
  "name": "station_to_xy",
  "error": {
    "type": "invalid_params",
    "message": "'station' is a required property",
    "valid_params_schema": {
      "type": "object",
      "properties": {
        "alignment": {
          "type": "string",
          "minLength": 1
        },
        "station": {
          "type": [
            "number",
            "string"
          ],
          "description": "display station: feet (8400) or '84+00.00'"
        },
        "offset": {
          "type": "number"
        },
        "region": {
          "type": "integer",
          "minimum": 1
        },
        "sheet": {
          "type": "string",
          "minLength": 1,
          "description": "also say where this falls on that sheet: adds on_sheet {viewport, sheet_point in paper inches, visible}"
        }
      },
      "required": [
        "station"
      ],
      "additionalProperties": false
    },
    "example": {
      "alignment": "ALIGN-1",
      "station": "84+00",
      "offset": 15
    }
  }
}
